package lk.repairdesk.api.service; import lk.repairdesk.api.domain.*; import lk.repairdesk.api.dto.DeviceDtos.*; import lk.repairdesk.api.exception.ResourceNotFoundException; import lk.repairdesk.api.repository.DeviceRepository; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class DeviceService {private final DeviceRepository repo;private final CurrentUserService current;public DeviceService(DeviceRepository r,CurrentUserService c){repo=r;current=c;} @Transactional public Response create(Request r){var d=new Device();d.setOwner(current.get());apply(d,r);return map(repo.save(d));} @Transactional(readOnly=true) public Page<Response> mine(Pageable p){return repo.findByOwnerId(current.get().getId(),p).map(this::map);} @Transactional(readOnly=true) public Device owned(Long id){var d=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Device not found"));var u=current.get();if(!d.getOwner().getId().equals(u.getId())&&u.getRole()!=Role.ADMIN)throw new IllegalArgumentException("Device is not owned by the current user");return d;} private void apply(Device d,Request r){d.setCategory(r.category());d.setBrand(r.brand().trim());d.setModel(r.model().trim());d.setSerialNumber(r.serialNumber());d.setPurchasePrice(r.purchasePrice());d.setPurchaseDate(r.purchaseDate());d.setNotes(r.notes());} private Response map(Device d){return new Response(d.getId(),d.getCategory(),d.getBrand(),d.getModel(),d.getSerialNumber(),d.getPurchasePrice(),d.getPurchaseDate(),d.getNotes(),d.getCreatedAt());}}